name: Community PR Permissions Check

on:
  pull_request:
    types: [opened, synchronize, reopened, edited]

permissions:
  pull-requests: write
  contents: read

jobs:
  check-permissions:
    runs-on: ubuntu-latest
    if: ${{ github.event.pull_request.head.repo.full_name != github.repository }}
    steps:
      - name: Check if PR is from a fork
        run: |
          echo "This PR is from a fork: ${{ github.event.pull_request.head.repo.full_name }}"
          echo "Repository: ${{ github.repository }}"

      - name: Check for restricted file changes
        id: check-files
        uses: actions/github-script@v7
        with:
          script: |
            const restrictedPaths = [
              '.github/',
              'airbyte-ci/',
              'airbyte-integrations/bases/',
              'airbyte-integrations/bases/base-normalization/',
              'airbyte-integrations/bases/base-python/',
              'airbyte-integrations/bases/base-java/',
              'airbyte-integrations/bases/base-image/',
              'airbyte-integrations/connectors/source-postgres/',
              'airbyte-integrations/connectors/source-mysql/',
              'airbyte-integrations/connectors/source-snowflake/',
              'airbyte-integrations/connectors/source-bigquery/',
              'airbyte-integrations/connectors/source-redshift/',
              'airbyte-integrations/connectors/source-azure-blob/',
              'airbyte-integrations/connectors/source-aws-s3/',
              'airbyte-integrations/connectors/source-gcs/',
              'airbyte-integrations/connectors/source-azure-blob-storage/'
            ];

            const files = context.payload.pull_request.changed_files || 0;
            if (files > 0) {
              const response = await github.rest.pulls.listFiles({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: context.issue.number
              });

              for (const file of response.data) {
                for (const restrictedPath of restrictedPaths) {
                  if (file.filename.startsWith(restrictedPath)) {
                    core.setFailed(`Community PRs cannot modify files in restricted path: ${restrictedPath}. File: ${file.filename}`);
                    return;
                  }
                }
              }
            }

            core.info("No restricted file changes detected.");
